UPDATE group_buy_market_better.group_team
SET current_num = current_num + 1
WHERE activity_id = #{activityId}
  AND group_team_id = #{groupTeamId}

UPDATE group_buy_market_better.group_team
SET team_status = 2
WHERE activity_id = #{activityId}
  AND group_team_id = #{groupTeamId}
  AND team_status = 0

UPDATE group_buy_market_better.group_team
SET current_num = current_num - 1
WHERE activity_id = #{activityId}
  AND group_team_id = #{groupTeamId}
  AND team_status = 0
